fn starts_with(s: &[char], p: &[char]) -> bool {
    // If the prefix is empty, return true
    if p.is_empty() {
        return true;
    }
    // If the sequence is shorter than the prefix, return false
    if s.len() < p.len() {
        return false;
    }
    // Check if the sequence matches the prefix
    s.iter().zip(p.iter()).all(|(sc, pc)| sc == pc)
}

fn has_prefix(v: &Vec<char>, p: &Vec<char>) -> bool {
    starts_with(v, p)
}

fn filter_by_prefix(xs: Vec<Vec<char>>, p: Vec<char>) -> Vec<Vec<char>> {
    xs.into_iter()
        .filter(|seq| has_prefix(seq, &p))
        .collect()
}

// Example usage
fn main() {
    let sequences = vec![
        vec!['a', 'b', 'c'],
        vec!['a', 'b', 'd'],
        vec!['c', 'd', 'e'],
        vec!['a', 'b'],
    ];
    let prefix = vec!['a', 'b'];
    
    let filtered = filter_by_prefix(sequences, prefix);
    
    for seq in filtered {
        println!("{:?}", seq);
    }
}